    self: Pin<&mut Self>,
    cx: &mut Context<'_>,
    dst: EncodeBuf<'_>,
) -> Poll<Result<(), Status>> {
    match self.state {
        State::CpuReady(item) => {
            dst.put(item);
            self.state = State::Idle;
            Poll::Ready(Ok(()))
        }
