    self: Pin<&mut Self>,
    item: Self::Item,
    dst: EncodeBufOwned,
) -> Result<(), Self::Error>;

fn poll_encode(
    self: Pin<&mut Self>,
    cx: &mut Context<'_>,
) -> Poll<Result<EncodeBufOwned, Self::Error>>;
```

This preserves zero-copy direct-DMA potential, but `EncodeBufOwned` becomes a real owned object rather than a borrowed `EncodeBuf<'_>`.

