        Self::YieldingCpu(PendingYieldingCpuCopy::new(source, buf))
    }

    fn poll(&mut self, cx: &mut Context<'_>) -> Poll<Result<EncodeBuffer, Status>> {
        match self {
            PendingCopy::Dsa(copy) => copy.as_mut().poll(cx),
