540:        if self.remaining > u32::MAX as usize {
541:            return Err(Status::internal(format!(
542:                "async dsa bytes encode cannot copy remaining {} bytes; maximum DSA transfer is {} bytes",
543:                self.remaining,
544:                u32::MAX
545:            )));
546:        }
