556:    ) -> Result<DsaRetryAction, Status> {
557:        let raw_status = completion.status();
558:        let status = DsaCompletionStatus::mask(raw_status);
559:        if status == DsaCompletionStatus::Success.as_u8() {
560:            return Ok(DsaRetryAction::Complete);
561:        }
