582:    fn handle_page_fault(
583:        &mut self,
584:        raw_status: u8,
585:        bytes_completed: u32,
586:        fault_addr: u64,
587:        device_path: &PathBuf,
588:    ) -> Result<(), Status> {
589:        if self.retry_count >= self.max_retries {
590:            return Err(Status::internal(format!(
591:                "async dsa bytes encode page-fault retry limit exceeded on {} for {} bytes: retries={} remaining={} fault_addr={fault_addr:#x}",
592:                device_path.display(),
593:                self.original_len,
594:                self.retry_count,
595:                self.remaining
596:            )));
597:        }
598:
599:        let completed = bytes_completed as usize;
600:        if completed > self.remaining {
601:            return Err(Status::internal(format!(
602:                "async dsa bytes encode page fault on {} reported bytes_completed={} beyond remaining {} for {} byte transfer",
603:                device_path.display(),
604:                completed,
605:                self.remaining,
606:                self.original_len
607:            )));
608:        }
609:
610:        if completed == 0 {
611:            self.no_progress_retry_count += 1;
612:            if self.no_progress_retry_count > MAX_NO_PROGRESS_PAGE_FAULT_RETRIES {
613:                return Err(Status::internal(format!(
614:                    "async dsa bytes encode made no progress after {} page-fault retries on {} for {} bytes: remaining={} fault_addr={fault_addr:#x}",
615:                    self.no_progress_retry_count,
616:                    device_path.display(),
617:                    self.original_len,
618:                    self.remaining
619:                )));
620:            }
621:        } else {
622:            self.no_progress_retry_count = 0;
623:        }
