625:        touch_fault_addr(raw_status, fault_addr)?;
626:
627:        if completed == self.remaining {
628:            return Err(Status::internal(format!(
629:                "async dsa bytes encode page fault on {} left no remaining bytes to retry for {} byte transfer",
630:                device_path.display(),
631:                self.original_len
632:            )));
633:        }
